def transform(grid):
    n, m = len(grid), len(grid[0])
    diagonals = {}
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v:
                diagonals.setdefault(c - r, set()).add(v)

    # Find the shortest repeating diagonal period consistent with all
    # observed diagonal colors.
    period = 1
    while period <= n + m:
        residues = {}
        ok = True
        for d, colors in diagonals.items():
            for color in colors:
                k = d % period
                if k in residues and residues[k] != color:
                    ok = False
                    break
                residues[k] = color
            if not ok:
                break
        if ok:
            break
        period += 1

    # Fill unobserved positions in the cycle by extending the observed
    # diagonal colors to their nearest known residue.
    if not residues:
        return [[0 for _ in range(m)] for _ in range(n)]
    cycle = []
    known = sorted(residues)
    for k in range(period):
        if k in residues:
            cycle.append(residues[k])
        else:
            near = min(known, key=lambda x: min((k-x) % period, (x-k) % period))
            cycle.append(residues[near])

    return [[cycle[(c-r) % period] for c in range(m)] for r in range(n)]
